/// <summary>
/// PaffH 15.11.21
/// </summary>
protected void new()
{
    super();
    this.initColorScheme = true;
    this.colorScheme = FormColorScheme::RGB;
    this.foregroundColor = WinAPI::RGB2int(255,0,0);     // red
    this.backgroundColor = WinAPI::RGB2int(255,255,0);   // yellow
}
